-- =========================================================
--  TORONTO BUILDING PERMITS DATABASE SCHEMA (MySQL Version)
-- =========================================================

CREATE SCHEMA TorontoBuildingPermits;
USE TorontoBuildingPermits;

CREATE TABLE Structure_Type (
    structure_type_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    structure_type_name VARCHAR(255) UNIQUE NOT NULL
);


CREATE TABLE Work_Type (
    work_type_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    work_type_name VARCHAR(255) UNIQUE NOT NULL
);


CREATE TABLE Permit_Status (
    status_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    status_name VARCHAR(255) UNIQUE NOT NULL
);


CREATE TABLE Use_Type (
    use_type_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    use_type_name VARCHAR(500) UNIQUE NOT NULL
);


CREATE TABLE Permit_Type (
    permit_type_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    permit_type_name VARCHAR(100) UNIQUE NOT NULL
);


CREATE TABLE Ward (
    ward_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    ward_grid VARCHAR(20) NOT NULL,
    geo_id VARCHAR(50) NOT NULL,
    ward_name VARCHAR(100),
    UNIQUE KEY unique_ward (ward_grid, geo_id)
);


CREATE TABLE Builder (
    builder_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    builder_name VARCHAR(255)
);


CREATE TABLE Street (
    street_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    street_name VARCHAR(100) NOT NULL,
    street_type VARCHAR(50) NOT NULL,
    street_direction VARCHAR(10) NOT NULL
);


CREATE TABLE Address (
    address_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    street_num VARCHAR(20) NOT NULL,
    postal VARCHAR(10) NOT NULL,
    street_id INT UNSIGNED NOT NULL,
    CONSTRAINT fk_address_street FOREIGN KEY (street_id)
        REFERENCES Street(street_id)
        ON DELETE RESTRICT
        ON UPDATE CASCADE
);


CREATE TABLE Permit (
    permit_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    permit_num VARCHAR(50) UNIQUE NOT NULL,
    revision_num VARCHAR(10) NOT NULL,
    permit_type_id INT UNSIGNED NOT NULL,
    application_date DATE NOT NULL,
    issued_date DATE,
    completed_date DATE,
    est_const_cost DECIMAL(15,2),
    description TEXT NOT NULL,
    dwelling_units_created INT NOT NULL DEFAULT 0,
    dwelling_units_lost INT NOT NULL DEFAULT 0,
    ward_id INT UNSIGNED,
    structure_type_id INT UNSIGNED NOT NULL,
    work_type_id INT UNSIGNED NOT NULL,
    status_id INT UNSIGNED NOT NULL,
    builder_id INT UNSIGNED,
    address_id INT UNSIGNED NOT NULL,
    CONSTRAINT fk_permit_permittype FOREIGN KEY (permit_type_id)
        REFERENCES Permit_Type(permit_type_id),
    CONSTRAINT fk_permit_ward FOREIGN KEY (ward_id)
        REFERENCES Ward(ward_id),
    CONSTRAINT fk_permit_structure FOREIGN KEY (structure_type_id)
        REFERENCES Structure_Type(structure_type_id),
    CONSTRAINT fk_permit_work FOREIGN KEY (work_type_id)
        REFERENCES Work_Type(work_type_id),
    CONSTRAINT fk_permit_status FOREIGN KEY (status_id)
        REFERENCES Permit_Status(status_id),
    CONSTRAINT fk_permit_builder FOREIGN KEY (builder_id)
        REFERENCES Builder(builder_id),
    CONSTRAINT fk_permit_address FOREIGN KEY (address_id)
        REFERENCES Address(address_id)
);




























































CREATE TABLE Permit_Use (
    permit_id INT UNSIGNED NOT NULL,
    use_type_id INT UNSIGNED NOT NULL,
    use_role ENUM('CURRENT','PROPOSED') NOT NULL,
    PRIMARY KEY (permit_id, use_type_id, use_role),
    CONSTRAINT fk_permit_use_permit FOREIGN KEY (permit_id)
        REFERENCES Permit(permit_id)
        ON DELETE CASCADE,
    CONSTRAINT fk_permit_use_usetype FOREIGN KEY (use_type_id)
        REFERENCES Use_Type(use_type_id)
);





















































CREATE TABLE Project_Category (
    category_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    category_name VARCHAR(100) UNIQUE NOT NULL
);


CREATE TABLE Permit_Category (
    permit_id INT UNSIGNED NOT NULL,
    category_id INT UNSIGNED NOT NULL,
    PRIMARY KEY (permit_id, category_id),
    CONSTRAINT fk_permitcat_permit FOREIGN KEY (permit_id)
        REFERENCES Permit(permit_id)
        ON DELETE CASCADE,
    CONSTRAINT fk_permitcat_category FOREIGN KEY (category_id)
        REFERENCES Project_Category(category_id)
);


